window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1a4ec2de07568e8e"]={"versions": [{"id": "FIG-1a4ec2de07568e8e", "releases": ["R2.1.20", "R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Schichtenstrukturdiagramm des AUTOSAR PDU Routers (PDU Router / PduR) innerhalb des AUTOSAR-Basissoftware-Kommunikationsstacks (Classic Platform). Das Diagramm stellt die interne Zerlegung des PDU Routers sowie seine hierarchischen und lateralen Einbettungen zwischen oberen Kommunikationsmodulen, Protokoll-Multiplexing und unteren Kommunikationsabstraktionsschichten dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Komponenten und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><strong>PDU Router (PduR)</strong> (blaue Box): Bestehend aus Rahmenstruktur mit oberer/unterer API-Ebene, der Kernausführungseinheit <strong>PDU Router Engine</strong> (mit integriertem Block <strong>Minimum Routing Capability</strong>) sowie den konfigurierbaren statischen Nachschlagestrukturen <strong>PDU Router routing tables</strong>.\n</li><li><strong>Obere Schichten / Benutzer</strong> (orange Boxen, oben):\n<ul class=\"fig-list\"><li><strong>COM (incl. Signal GW)</strong>: Anbindung über bidirektionale Pfeile.\n</li><li><strong>Diagnostic Communication Manager (Dcm)</strong>: Anbindung über bidirektionale Pfeile.\n</li></ul>\n</li><li><strong>Laterale Anbindung</strong> (orange Box, links):\n<ul class=\"fig-list\"><li><strong>IPDUM</strong> (IPDU Multiplexer): Direkte bidirektionale Verbindung zum PDU Router.\n</li></ul>\n</li><li><strong>Transportschicht (TP)</strong> (orange Zwischenschicht):\n<ul class=\"fig-list\"><li><strong>FlexRay TP</strong>: Tauscht I-PDUs mit dem PDU Router aus.\n</li><li><strong>CAN TP</strong>: Tauscht I-PDUs mit dem PDU Router aus.\n</li></ul>\n</li><li><strong>Kommunikations-Hardware-Abstraktionsschicht</strong> (untere hellbraune Schicht, <em>Communication HW Abstraction</em>):\n<ul class=\"fig-list\"><li><strong>FlexRay Interface</strong>: Direkte I-PDU-Verbindung zum PDU Router; N-PDU-Austausch mit FlexRay TP.\n</li><li><strong>CAN Interface</strong>: Direkte I-PDU-Verbindung zum PDU Router; N-PDU-Austausch mit CAN TP.\n</li><li><strong>LIN Interface (incl. LIN TP)</strong>: Direkte I-PDU-Verbindung zum PDU Router (LIN TP ist integraler Bestandteil des Interface).\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Alle Kommunikationsbeziehungen zum PduR sind als bidirektionale I-PDU-Pfade modelliert; zwischen Interfaces und Transportprotokollen werden N-PDUs übergeben.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm visualisiert statische Daten- und Steuerpfade für das PDU-Routing im laufenden Betrieb:</p>\n<ul class=\"fig-list\"><li><strong>Vertikales Routing</strong>: I-PDUs werden zwischen oberen Modulen (COM, DCM) und unteren Schichten (Bus-Interfaces oder TPs) über die Routing Engine anhand der Routing-Tabellen weitergeleitet.\n</li><li><strong>Transportschicht vs. Interface</strong>: Für segmentierte Diagnose- oder Langnachrichten laufen I-PDUs über FlexRay TP / CAN TP (mit N-PDU-Konvertierung zu den Interfaces), während unsegmentierte Daten direkt zwischen PDU Router und Bus-Interfaces (FlexRay Interface, CAN Interface, LIN Interface) transferiert werden.\n</li><li><strong>Multiplexing</strong>: Das IPDUM bindet direkt an den PDU Router an, um Signale/PDUs dynamisch zu multiplexen oder zu demultiplexen.\n</li><li><strong>Routing-Minimalbetrieb</strong>: Die PDU Router Engine verfügt über eine elementare Basisfunktionalität („Minimum Routing Capability“) zur Ausführung unkomplizierter Weiterleitungen.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ definiert das Diagramm die I-PDU- und N-PDU-Schnittstellengrenzen des PDU Routers:</p>\n<ul class=\"fig-list\"><li>Der PDU Router agiert ausschließlich auf I-PDU-Ebene und aggregiert keine Rohrahmen oder Transport-Frames (N-PDUs verbleiben zwischen TP und Interface).\n</li><li>Er bildet die zentrale Trennlinie zwischen protokollspezifischer Busabstraktion (CAN, LIN, FlexRay) und den busunabhängigen Applikations- bzw. Diagnoseschichten.\n</li><li>Konfigurationsrelevanz: Die Routing-Beziehungen zwischen Quelle und Ziel (COM, DCM, Interfaces, TPs, IPDUM) müssen statisch in den <em>PDU Router routing tables</em> hinterlegt werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f93946abaf9b6ad0", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Schichtenstrukturdiagramm des AUTOSAR PDU Routers (PDU Router / PduR) innerhalb des AUTOSAR-Basissoftware-Kommunikationsstacks (Classic Platform). Das Diagramm stellt die interne Zerlegung des PDU Routers sowie seine hierarchischen und lateralen Einbettungen zwischen oberen Kommunikationsmodulen, Protokoll-Multiplexing und unteren Kommunikationsabstraktionsschichten dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Komponenten und Schnittstellen:</p>\n<ul class=\"fig-list\"><li><strong>PDU Router (PduR)</strong> (blaue Box): Bestehend aus Rahmenstruktur mit oberer/unterer API-Ebene, der Kernausführungseinheit <strong>PDU Router Engine</strong> (mit internem Teilfunktionsblock ohne Textauszeichnung) sowie den konfigurierbaren statischen Nachschlagestrukturen <strong>PDU Router routing tables</strong>.\n</li><li><strong>Obere Schichten / Benutzer</strong> (orange Boxen, oben):\n<ul class=\"fig-list\"><li><strong>COM (incl. Signal GW)</strong>: Anbindung über bidirektionale Pfeile.\n</li><li><strong>Diagnostic Communication Manager (Dcm)</strong>: Anbindung über bidirektionale Pfeile.\n</li></ul>\n</li><li><strong>Laterale Anbindung</strong> (orange Box, links):\n<ul class=\"fig-list\"><li><strong>IPDUM</strong> (IPDU Multiplexer): Direkte bidirektionale Verbindung zum PDU Router.\n</li></ul>\n</li><li><strong>Transportschicht (TP)</strong> (orange Zwischenschicht):\n<ul class=\"fig-list\"><li><strong>FlexRay TP</strong>: Tauscht I-PDUs mit dem PDU Router aus.\n</li><li><strong>CAN TP</strong>: Tauscht I-PDUs mit dem PDU Router aus.\n</li></ul>\n</li><li><strong>Kommunikations-Hardware-Abstraktionsschicht</strong> (untere hellbraune Schicht, <em>Communication HW Abstraction</em>):\n<ul class=\"fig-list\"><li><strong>FlexRay Interface</strong>: Direkte I-PDU-Verbindung zum PDU Router; N-PDU-Austausch mit FlexRay TP.\n</li><li><strong>CAN Interface</strong>: Direkte I-PDU-Verbindung zum PDU Router; N-PDU-Austausch mit CAN TP.\n</li><li><strong>LIN Interface (incl. LIN TP)</strong>: Direkte I-PDU-Verbindung zum PDU Router (LIN TP ist integraler Bestandteil des Interface).\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Alle Kommunikationsbeziehungen zum PduR sind als bidirektionale I-PDU-Pfade modelliert; zwischen Interfaces und Transportprotokollen werden N-PDUs übergeben.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm visualisiert statische Daten- und Steuerpfade für das PDU-Routing im laufenden Betrieb:</p>\n<ul class=\"fig-list\"><li><strong>Vertikales Routing</strong>: I-PDUs werden zwischen oberen Modulen (COM, DCM) und unteren Schichten (Bus-Interfaces oder TPs) über die Routing Engine anhand der Routing-Tabellen weitergeleitet.\n</li><li><strong>Transportschicht vs. Interface</strong>: Für segmentierte Diagnose- oder Langnachrichten laufen I-PDUs über FlexRay TP / CAN TP (mit N-PDU-Konvertierung zu den Interfaces), während unsegmentierte Daten direkt zwischen PDU Router und Bus-Interfaces (FlexRay Interface, CAN Interface, LIN Interface) transferiert werden.\n</li><li><strong>Multiplexing</strong>: Das IPDUM bindet direkt an den PDU Router an, um Signale/PDUs dynamisch zu multiplexen oder zu demultiplexen.\n</li><li><strong>Routing-Engine</strong>: Die PDU Router Engine übernimmt die Weiterleitungslogik anhand der Tabelleneinträge.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ definiert das Diagramm die I-PDU- und N-PDU-Schnittstellengrenzen des PDU Routers:</p>\n<ul class=\"fig-list\"><li>Der PDU Router agiert ausschließlich auf I-PDU-Ebene und aggregiert keine Rohrahmen oder Transport-Frames (N-PDUs verbleiben zwischen TP und Interface).\n</li><li>Er bildet die zentrale Trennlinie zwischen protokollspezifischer Busabstraktion (CAN, LIN, FlexRay) und den busunabhängigen Applikations- bzw. Diagnoseschichten.\n</li><li>Konfigurationsrelevanz: Die Routing-Beziehungen zwischen Quelle und Ziel (COM, DCM, Interfaces, TPs, IPDUM) müssen statisch in den <em>PDU Router routing tables</em> hinterlegt werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-1a4ec2de07568e8e", "to": "FIG-f93946abaf9b6ad0", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>PDU Router Engine: Der innere Kasten innerhalb der PDU Router Engine enthält keine Textbeschriftung mehr („Minimum Routing Capability“ wurde entfernt; der Kasten selbst bleibt als leere Kontur erhalten).\n</li></ul>"}]};
